         style="background-image: url('${story.image}');"
       >
         <div class="editorial-meta">
           <span>${story.category}</span>
           <span>${story.readTime}</span>
         </div>
         <h3>${story.title}</h3>
         <p class="subtle">${story.copy}</p>
       </article>
     `;

     const EditorialSection = () => `
       <section class="section-panel" id="editorial">
         <div class="section-header">
           <div class="section-heading">
             <h2>Editorial content</h2>
             <p>
               Stories, guides, and seasonal inspiration that connect product, lifestyle, and design.
             </p>
           </div>
           <a class="pill" href="#featured">Shop the stories</a>
         </div>
         <div class="grid-editorial">
           ${editorial.map(EditorialCard).join("")}
         </div>
       </section>
     `;

     const MembershipSection = () => `
       <section class="promo-panel" id="membership">
         <div>
           <span class="eyebrow">Members club / by invitation</span>
           <h3>Unlock exclusive pricing, early access launches, and concierge-style recommendations.</h3>
           <p class="subtle">
             Join the Nocturne membership for private sale alerts, tailored product edits, and first access to editorial events.
           </p>
         </div>
         <a class="button" href="#app">Request Access</a>
       </section>
     `;

     const Footer = () => `
       <footer>
         <span>© 2026 Nocturne Retail. Designed for elevated shopping experiences.</span>
         <span>Featured products, deals, and editorial crafted in a single standalone document.</span>
       </footer>
     `;

     const App = () => `
       <div class="page-shell">
         ${Header()}
         <main>
           ${Hero()}
           ${FeaturedSection()}
           ${DealsSection()}
           ${EditorialSection()}
           ${MembershipSection()}
         </main>
         ${Footer()}
       </div>
     `;

     document.getElementById("app").innerHTML = App();
   </script>
 </body>
 </html>

')
